// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skill.executorimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.Result/** * NOUS — System operation executor. * * Executes [SystemOperation]s against Android system services (CameraManager, * AudioManager, WindowManager, etc.). Skills and rules use this to perform * side-effectful actions on the device. * * Real implementation: :feature:system's `SystemOperationExecutorImpl` (bound * via SystemModule's Hilt graph). Brain uses this interface to stay testable * without Android system services. * * Test fake: `FakeSystemOperationExecutor` in * `src/test/kotlin/.../skill/executor/` — records operations without executing. * * @see <a href="docs/spec/module2-spec-review.pdf">§3.2 SystemOperation</a> */interface SystemOperationExecutor {    /** Execute a single system operation. */    suspend fun execute(operation: SystemOperation): Result<Unit>    /** Execute multiple operations in sequence. */    suspend fun executeAll(operations: List<SystemOperation>): Result<List<Result<Unit>>>}